export function toCSV(rows){const columns=['qa','id','linkId','intendedName','intendedEmail','declaredName','declaredEmail','identityConfidence','openedAt','lastSeenAt','visibleSeconds','stages','completed','parentLinkId','eventCount'];const cell=v=>{let s=Array.isArray(v)?v.join('; '):String(v??'');if(/^\s*[=+@\-\t\r\n]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};return [columns.map(cell).join(','),...rows.map(r=>columns.map(c=>cell(r[c])).join(','))].join('\r\n');}
if(typeof document!=='undefined'){
 const $=s=>document.querySelector(s);let key='',report=null;
 const status=s=>{$('#status').textContent=s;};
 async function api(action,body){const r=await fetch('/api/engagement?action='+action,{method:body?'POST':'GET',cache:'no-store',credentials:'omit',headers:{Authorization:'Bearer '+key,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error??'Storage is not configured');return data;}
 function table(target,columns,rows,empty){const root=$(target);root.replaceChildren();if(!rows.length){const p=document.createElement('p');p.className='empty';p.textContent=empty;root.append(p);return;}const wrap=document.createElement('div');wrap.className='table-wrap';const t=document.createElement('table'),head=t.createTHead().insertRow();for(const [label]of columns){const th=document.createElement('th');th.textContent=label;head.append(th);}for(const row of rows){const tr=t.createTBody().insertRow();for(const [,get]of columns){const td=tr.insertCell();const value=get(row);if(value instanceof Node)td.append(value);else td.textContent=String(value??'');}}wrap.append(t);root.append(wrap);}
 function render(){table('#links',[['Record',r=>r.qa?'TEST FIXTURE':'Recipient link'],['Intended recipient',r=>r.intendedName+' / '+r.intendedEmail],['Expires',r=>new Date(r.expiresAt).toISOString()],['Parent',r=>r.parentId??'Original'],['Link / revoke',r=>{const box=document.createElement('div'),a=document.createElement('a');a.href=r.shareURL;a.textContent=r.shareURL;box.append(a);const b=document.createElement('button');b.textContent=r.revoked?'Revoked':'Revoke link + descendants';b.disabled=r.revoked;b.onclick=async()=>{try{await api('revoke',{token:r.id});await refresh();}catch(e){status(e.message);}};box.append(b);return box;}]],report.links,'No recipient links have been created.');table('#sessions',[['Record',r=>r.qa?'TEST FIXTURE':'Consented session'],['Intended recipient',r=>r.intendedName+' / '+r.intendedEmail],['Declared identity (not verified)',r=>r.declaredName+' / '+r.declaredEmail+' (self-reported)'],['Opened (UTC)',r=>r.openedAt],['Last seen (UTC)',r=>r.lastSeenAt],['Visible seconds',r=>r.visibleSeconds],['Stages / completion',r=>r.stages.join(', ')+' / '+(r.completed?'complete':'not complete')],['Parent link',r=>r.parentLinkId??'Original']],report.sessions,'No consented viewing sessions recorded. No sample customers.');table('#shares',[['Record',r=>r.qa?'TEST FIXTURE':'Share-link created'],['Created (UTC)',r=>r.createdAt],['Parent link',r=>r.parentLinkId],['Child link',r=>r.linkId],['Delivery',()=> 'Not observed; creation only']],report.shares,'No share links created. Off-app forwarding is not detectable.');}
 async function refresh(){report=await api('report');render();status('Connected. Private storage write/read probe succeeded. '+report.sessions.length+' consented sessions (includes labeled QA fixtures).');}
 $('#connect').onsubmit=async e=>{e.preventDefault();key=$('#owner-key').value;$('#owner-key').value='';try{await api('health',{});await refresh();$('#workspace').hidden=false;}catch(err){key='';report=null;$('#workspace').hidden=true;status('Not connected: '+err.message);}};
 $('#lock').onclick=()=>{key='';report=null;$('#owner-key').value='';$('#workspace').hidden=true;for(const id of ['#links','#sessions','#shares','#created'])$(id).replaceChildren();status('Locked. Owner key and report cleared from this page.');};
 $('#create').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const result=await api('create-link',{proposalId:'factory-line-v3',intendedName:f.get('intendedName'),intendedEmail:f.get('intendedEmail'),expiresDays:Number(f.get('expiresDays')),qa:f.get('qa')==='on'});const a=document.createElement('a');a.href=result.shareURL;a.textContent=result.shareURL;$('#created').replaceChildren(a);const copy=document.createElement('button');copy.textContent='Copy link';copy.onclick=async()=>{try{await navigator.clipboard.writeText(result.shareURL);copy.textContent='Copied (not sent)';}catch{status('Clipboard unavailable. Select and copy the link.');}};$('#created').append(copy);await refresh();}catch(err){status(err.message);}};
 $('#refresh').onclick=()=>refresh().catch(e=>status(e.message));
 function download(content,type,name){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 $('#json').onclick=()=>{if(report)download(JSON.stringify(report,null,2),'application/json','proposal-engagement.json');};$('#csv').onclick=()=>{if(report)download(toCSV(report.sessions),'text/csv;charset=utf-8','proposal-engagement.csv');};
}
